sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float segments;
uniform float angle;
uniform float mirror;
uniform float direction;
uniform float4 screen;
uniform float edgeStyle;
half4 main(float2 coord) {
    if (edgeStyle > 0.5 && segments <= 0.0) return half4(0.0);
    float2 c = center * size;
    float flip = direction > 0.5 ? -1.0 : 1.0;
    float2 d = (coord - c) * float2(1.0, flip);
    float radius = length(d);
    if (radius < 0.00001) return image.eval(c);
    float slice = 6.2831853 / (edgeStyle > 0.5 ? segments : max(floor(segments), 1));
    float a = mod(atan(d.y, d.x) - (edgeStyle > 0.5 ? slice * 0.5 * step(0.5, mirror) : radians(angle)), slice);
    a = (mirror > 0.5 ? min(a, slice - a) : a) + radians(angle);
    float2 q = c + radius * float2(cos(a), flip * sin(a));
    return image.eval(edgeStyle > 0.5 ? clamp(q, screen.xy + 0.5, screen.xy + screen.zw - 0.5) : q);
}
